/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-combobox,
:where([data-moru-registry]) .ui-combobox-popup {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
}

:where([data-moru-registry]) .ui-combobox,
:where([data-moru-registry]) .ui-combobox-popup {
  --ui-size-icon: var(--ui-icon-size-md, 16px);
  --ui-advanced-border: var(--ui-border-width, 1px);
  --ui-advanced-height: var(--ui-control-height-md, 40px);
  --ui-advanced-padding: var(--ui-control-padding-x-md, 12px);
  --ui-advanced-resolved-height: max(
    var(--ui-advanced-height),
    calc(
      max(
          var(--ui-type-label-size, 14px) * var(--ui-type-label-line-height, 1.45),
          var(--ui-size-icon)
        ) +
        var(--ui-space, 4px) * 2 + var(--ui-advanced-border) * 2
    )
  );
  --ui-advanced-inner-height: calc(
    var(--ui-advanced-resolved-height) - var(--ui-advanced-border) * 2
  );
}

:where([data-moru-registry]) .ui-combobox[data-size='sm'],
:where([data-moru-registry]) .ui-combobox-popup[data-size='sm'] {
  --ui-size-icon: var(--ui-icon-size-sm, 14px);
  --ui-advanced-height: var(--ui-control-height-sm, 32px);
  --ui-advanced-padding: var(--ui-control-padding-x-sm, 10px);
}
:where([data-moru-registry]) .ui-combobox[data-size='lg'],
:where([data-moru-registry]) .ui-combobox-popup[data-size='lg'] {
  --ui-size-icon: var(--ui-icon-size-lg, 18px);
  --ui-advanced-height: var(--ui-control-height-lg, 48px);
  --ui-advanced-padding: var(--ui-control-padding-x-lg, 16px);
}

:where([data-moru-registry]) .ui-combobox {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: var(--ui-advanced-resolved-height);
  border: var(--ui-advanced-border) solid var(--ui-border, #e8e8e4);
  border-radius: var(--ui-radius, 6px);
  background: var(--ui-input-bg, #f0f0ed);
  transition:
    background-color var(--ui-duration, 160ms),
    border-color var(--ui-duration, 160ms),
    box-shadow var(--ui-duration, 160ms);
}
:where([data-moru-registry]) .ui-combobox:hover:not(:has(input:is(:disabled, [aria-busy='true']))):not(
    :has([aria-invalid='true'])
  ) {
  background: color-mix(in srgb, var(--ui-input-bg, #f0f0ed) 94%, var(--ui-text, #171717));
  border-color: var(--ui-border, #e8e8e4);
}
:where([data-moru-registry]) .ui-combobox:focus-within {
  border-color: var(--ui-focus-ring, #181818);
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: 2px;
}
:where([data-moru-registry]) .ui-combobox:has([aria-invalid='true']) {
  border-color: var(--ui-danger, #b34040);
  background: var(--ui-danger-soft, #f9efef);
  box-shadow: 0 0 0 1px var(--ui-error-ring, var(--ui-danger, #b34040));
  outline-color: var(--ui-error-ring, var(--ui-danger, #b34040));
}
:where([data-moru-registry]) .ui-combobox-input {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: var(--ui-advanced-inner-height);
  padding: var(--ui-space, 4px) var(--ui-advanced-padding);
  border: 0;
  border-radius: inherit;
  background: transparent;
  color: inherit;
  outline: none;
  font: inherit;
  font-size: var(--ui-type-label-size, 14px);
  line-height: var(--ui-type-label-line-height, 1.45);
  font-weight: var(--ui-type-body-weight, 400);
}
:where([data-moru-registry]) .ui-combobox-input::placeholder {
  color: var(--ui-muted, #6e6e6b);
  opacity: 1;
}
:where([data-moru-registry]) .ui-combobox-trigger,
:where([data-moru-registry]) .ui-combobox-clear {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: max(28px, var(--ui-advanced-height));
  min-height: var(--ui-advanced-inner-height);
  margin: 0;
  padding: var(--ui-space, 4px);
  border: 0;
  border-radius: max(2px, calc(var(--ui-radius, 6px) - 2px));
  background: transparent;
  color: var(--ui-muted, #6e6e6b);
  cursor: pointer;
}
:where([data-moru-registry]) .ui-combobox-clear {
  width: max(28px, calc(var(--ui-size-icon) + var(--ui-control-gap, 8px) * 2));
}
:where([data-moru-registry]) .ui-combobox-trigger > svg,
:where([data-moru-registry]) .ui-combobox-clear > svg,
:where([data-moru-registry]) .ui-combobox-check > svg {
  width: var(--ui-size-icon);
  height: var(--ui-size-icon);
  flex: none;
}
:where([data-moru-registry]) .ui-combobox-trigger:hover:not(:disabled),
:where([data-moru-registry]) .ui-combobox-clear:hover:not(:disabled) {
  background: var(--ui-control-hover-bg, #f3f3f1);
  color: var(--ui-text, #171717);
}
:where([data-moru-registry]) .ui-combobox:has(input:is(:disabled, [aria-busy='true'])) {
  border-color: var(--ui-disabled-border, var(--ui-border, #e8e8e4));
  background: var(--ui-disabled-bg, #f3f3f1);
  color: var(--ui-disabled-text, #a1a1aa);
  box-shadow: none;
}
:where([data-moru-registry]) .ui-combobox input:disabled,
:where([data-moru-registry]) .ui-combobox button:disabled {
  color: var(--ui-disabled-text, #a1a1aa);
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-combobox-positioner {
  z-index: 90;
  outline: 0;
  width: var(--anchor-width);
  max-width: calc(100vw - 24px);
}
:where([data-moru-registry]) .ui-combobox-popup {
  width: 100%;
  overflow: hidden;
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 8px 28px #00000016);
  transform-origin: var(--transform-origin);
  transition:
    opacity var(--ui-duration, 160ms),
    transform var(--ui-duration, 160ms);
}
:where([data-moru-registry]) .ui-combobox-list {
  max-height: min(280px, var(--available-height, 280px));
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--ui-space, 4px);
}
:where([data-moru-registry]) .ui-combobox-list:empty {
  padding: 0;
}
:where([data-moru-registry]) .ui-combobox-item {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--ui-control-gap, 8px);
  min-height: var(--ui-advanced-resolved-height);
  padding: var(--ui-space, 4px) var(--ui-advanced-padding);
  border-radius: max(2px, calc(var(--ui-radius, 6px) - 3px));
  outline: 0;
  cursor: pointer;
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
}
:where([data-moru-registry]) .ui-combobox-item[data-highlighted] {
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-combobox-item[data-selected] {
  color: var(--ui-primary-foreground, #fff);
  background: var(--ui-primary, #181818);
}
:where([data-moru-registry]) .ui-combobox-item[data-selected] .ui-combobox-description {
  color: inherit;
  opacity: 0.8;
}
:where([data-moru-registry]) .ui-combobox-item[data-disabled] {
  color: var(--ui-disabled-text, #a1a1aa);
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-combobox-copy {
  display: grid;
  min-width: 0;
  gap: calc(var(--ui-field-gap, 8px) / 2);
  overflow-wrap: anywhere;
}
:where([data-moru-registry]) .ui-combobox-description {
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  font-weight: var(--ui-type-caption-weight, 400);
  line-height: var(--ui-type-caption-line-height, 1.5);
}
:where([data-moru-registry]) .ui-combobox-check {
  display: inline-flex;
  flex: none;
  margin-inline-start: auto;
}
:where([data-moru-registry]) .ui-combobox-empty {
  margin: 0;
  color: var(--ui-muted, #6e6e6b);
  font-size: var(--ui-type-caption-size, 12px);
  text-align: center;
}
:where([data-moru-registry]) .ui-combobox-empty:not(:empty) {
  padding: calc(var(--ui-space, 4px) * 4);
}

:where([data-moru-registry]) .ui-combobox-trigger:focus-visible,
:where([data-moru-registry]) .ui-combobox-clear:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: 2px;
}
:where([data-moru-registry]) .ui-combobox-popup[data-starting-style],
:where([data-moru-registry]) .ui-combobox-popup[data-ending-style] {
  opacity: 0;
  transform: translateY(-4px);
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-combobox,
  :where([data-moru-registry]) .ui-combobox-popup {
    --ui-advanced-resolved-height: max(
      44px,
      var(--ui-advanced-height),
      calc(
        max(
            max(16px, var(--ui-type-label-size, 14px)) * var(--ui-type-label-line-height, 1.45),
            var(--ui-size-icon)
          ) +
          var(--ui-space, 4px) * 2 + var(--ui-advanced-border) * 2
      )
    );
  }
  :where([data-moru-registry]) .ui-combobox-trigger,
  :where([data-moru-registry]) .ui-combobox-clear {
    min-width: 44px;
  }
  :where([data-moru-registry]) .ui-combobox-input {
    font-size: max(16px, var(--ui-type-label-size, 13px));
  }
}

@media (forced-colors: active) {
  :where([data-moru-registry]) .ui-combobox {
    --ui-advanced-border: 1px;
    border: var(--ui-advanced-border) solid ButtonText;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-combobox,
  :where([data-moru-registry]) .ui-combobox-popup {
    transition: none;
  }
}

:where([data-moru-registry]) .ui-combobox[data-loading] {
  background: var(--ui-loading-bg, #f3f3f1);
  color: var(--ui-loading-text, #303030);
  cursor: progress;
}
:where([data-moru-registry]) .ui-combobox[data-loading] input,
:where([data-moru-registry]) .ui-combobox[data-loading] button {
  color: inherit;
  cursor: progress;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { forwardRef, useEffect, useId, useState, type AriaAttributes } from 'react'
import { Combobox as BaseCombobox } from '@base-ui/react/combobox'
import { cn } from './_lib/cn'
import { mergeDescriptionIds, useFieldContext } from './field-context'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './advanced-controls-shared.css'
import './combobox.css'

export interface ComboboxItem {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface ComboboxProps {
  items: ComboboxItem[]
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null) => void
  placeholder?: string
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-describedby'?: string
  'aria-invalid'?: AriaAttributes['aria-invalid']
  disabled?: boolean
  loading?: boolean
  readOnly?: boolean
  required?: boolean
  clearable?: boolean
  name?: string
  form?: string
  id?: string
  size?: 'sm' | 'md' | 'lg'
  className?: string
}

/** Searchable single selection. Public values remain stable strings, including in forms. */
export const Combobox = forwardRef<HTMLInputElement, ComboboxProps>(function Combobox(
  {
    items,
    value,
    defaultValue,
    onValueChange,
    placeholder: placeholderProp,
    'aria-label': ariaLabel,
    'aria-labelledby': labelledBy,
    'aria-describedby': describedBy,
    'aria-invalid': invalid,
    disabled,
    loading = false,
    readOnly,
    required,
    clearable = true,
    name,
    form,
    id,
    size = 'md',
    className,
  },
  ref,
) {
  const { t } = useI18n()
  const placeholder = placeholderProp ?? t('검색해서 선택하세요')

  const field = useFieldContext()
  const portalContainer = useThemePortalContainer()
  const triggerId = useId()
  const unavailable = disabled || loading
  const [open, setOpen] = useState(false)
  useEffect(() => {
    if (unavailable || readOnly) setOpen(false)
  }, [unavailable, readOnly])
  const resolveItem = (selected: string | null | undefined) =>
    selected == null
      ? null
      : (items.find((item) => item.value === selected) ?? { value: selected, label: selected })
  return (
    <BaseCombobox.Root<ComboboxItem>
      open={open && !unavailable && !readOnly}
      onOpenChange={(next, details) => {
        if (next && (unavailable || readOnly)) {
          details.cancel()
          return
        }
        setOpen(next)
      }}
      id={id ?? field?.controlId}
      items={items}
      value={value === undefined ? undefined : resolveItem(value)}
      defaultValue={resolveItem(defaultValue)}
      onValueChange={(item, details) => {
        if (unavailable || readOnly) {
          details.cancel()
          return
        }
        onValueChange?.(item?.value ?? null)
      }}
      isItemEqualToValue={(item, selected) => item.value === selected.value}
      itemToStringLabel={(item) =>
        items.find((option) => option.value === item.value)?.label ?? item.label
      }
      itemToStringValue={(item) => item.value}
      filter={(item, query) =>
        `${item.label} ${item.description ?? ''}`
          .toLocaleLowerCase()
          .includes(query.trim().toLocaleLowerCase())
      }
      autoHighlight
      // Busy locks the field with readOnly, not disabled, so typing focus is kept
      // while options load and the value still submits with the form.
      disabled={disabled}
      readOnly={readOnly || loading}
      name={name}
      form={form}
      required={required}
    >
      <BaseCombobox.InputGroup
        className={cn('ui-combobox', className)}
        data-size={size}
        data-loading={loading || undefined}
      >
        <BaseCombobox.Input
          ref={ref}
          aria-label={ariaLabel}
          aria-labelledby={labelledBy}
          aria-describedby={mergeDescriptionIds(describedBy, field?.describedBy)}
          aria-invalid={invalid ?? (field?.invalid || undefined)}
          aria-busy={loading || undefined}
          placeholder={placeholder}
          className="ui-combobox-input"
        />
        {clearable && !unavailable && !readOnly && (
          <BaseCombobox.Clear className="ui-combobox-clear" aria-label={t('선택 지우기')}>
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path
                d="m4 4 8 8m0-8-8 8"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
              />
            </svg>
          </BaseCombobox.Clear>
        )}
        <BaseCombobox.Trigger
          render={
            <button
              id={`${triggerId}-trigger`}
              role="button"
              tabIndex={-1}
              aria-haspopup="listbox"
            />
          }
          className="ui-combobox-trigger"
          aria-label={loading ? t('목록 불러오는 중') : t('선택 목록 열기')}
          disabled={unavailable || readOnly}
        >
          {loading ? (
            <span className="ui-loading-indicator" aria-hidden="true" />
          ) : (
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path
                d="m4 6 4 4 4-4"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          )}
        </BaseCombobox.Trigger>
      </BaseCombobox.InputGroup>
      <OverlayPortal portal={BaseCombobox.Portal} kind="combobox" container={portalContainer}>
        <BaseCombobox.Positioner className="ui-combobox-positioner" sideOffset={6}>
          <BaseCombobox.Popup className="ui-combobox-popup" data-size={size}>
            <BaseCombobox.Empty className="ui-combobox-empty">
              {t('검색 결과가 없습니다.')}
            </BaseCombobox.Empty>
            <BaseCombobox.List className="ui-combobox-list">
              {(item: ComboboxItem) => (
                <BaseCombobox.Item
                  key={item.value}
                  value={item}
                  disabled={item.disabled}
                  className="ui-combobox-item"
                >
                  <span className="ui-combobox-copy">
                    <span>{item.label}</span>
                    {item.description && (
                      <span className="ui-combobox-description">{item.description}</span>
                    )}
                  </span>
                  <BaseCombobox.ItemIndicator className="ui-combobox-check">
                    <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                      <path
                        d="m3 8 3 3 7-7"
                        stroke="currentColor"
                        strokeWidth="1.6"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  </BaseCombobox.ItemIndicator>
                </BaseCombobox.Item>
              )}
            </BaseCombobox.List>
          </BaseCombobox.Popup>
        </BaseCombobox.Positioner>
      </OverlayPortal>
    </BaseCombobox.Root>
  )
})
